 def size_image(match):
  tag=match.group(0)
  if ' width=' in tag:return tag
  source=re.search(r'src="([^"]+)"',tag)
  size=dimensions.get(Path(source[1]).name) if source else None
  return tag[:-1]+f' width="{size[0]}" height="{size[1]}">' if size else tag
 html=re.sub(r'<img\b[^>]*>',size_image,html)
